INSERT INTO public.quote_harian (teks, created_at) VALUES
  ('Jadilah seperti kereta; berkonsentrasi pada jalanmu dan pergi tanpa ragu-ragu!', '2026-07-31T03:59:19.931Z'::timestamptz),
  ('Sesungguhnya manusia itu ibarat lautan, maka jangan menghakimi kedalamannya sementara kamu tidak melihat apa-apa selain pantainya.', '2026-07-31T07:09:40.966Z'::timestamptz),
  ('Jangan jadikan penyemangat jadi salah niat', '2026-07-31T07:44:51.667Z'::timestamptz),
  ('Yang terjaga hanya untuk yang menjaga', '2026-07-31T07:54:13.123Z'::timestamptz),
  ('Secapek apapun kamu, hiduplah seolah-olah doamu terjawab besok', '2026-08-06T07:23:57.214Z'::timestamptz),
  ('Mungkin kita belum tau arahnya kemana, tapi semoga setiap langkah yang kita jalani selalu menuju hal yang baik.', '2026-08-06T07:24:37.708Z'::timestamptz),
  ('entah sebesar apapun tanggung jawab di pundak kita, dan entah seberisik apapun isi kepala kita, Semoga Allah mampukan & mudahkan setiap proses yang sedang kita jalani.', '2026-08-06T07:25:34.901Z'::timestamptz),
  ('Jika semua tidak berjalan seperti yang ktia mau, berarti kita sedang menjalankan apa yang Allah mau.', '2026-08-06T07:26:08.909Z'::timestamptz),
  ('Hiduplah dengan hati yang lapang dan bersih, karena ketenangan adalah bentuk bahagia yang paling nyata.', '2026-08-06T07:26:44.159Z'::timestamptz),
  ('Hati yang tenang, dimulai dengan tidak membandingkan nikmatmu dengan nikmat orang lain.', '2026-08-06T07:27:18.002Z'::timestamptz),
  ('Sesedih apapun, ini bukan neraka. Sebahagia apapun, ini bukan surga. semoga kita bisa sedih dan bahagia secukupnya. it''s just dunia.', '2026-08-06T07:28:18.396Z'::timestamptz);
