  ('absensi', 'kelas_4_2026-08-05', 'create'::audit_action, jsonb_build_object('catatan', 'Input Absen kelas "4": 2 santri'), '2026-08-06T07:24:32.858Z'::timestamptz),
  ('quote_harian', '6', 'create'::audit_action, jsonb_build_object('catatan', 'Tambah quote: "Mungkin kita belum tau arahnya kemana, tapi semoga setiap langkah yang kita jalani selalu menuju hal yang baik."'), '2026-08-06T07:24:38.243Z'::timestamptz),
